{"explanation":"Slice the cone and cylinder at the same distance from the cone’s tip. At a fraction u of the total height, similar triangles give the cone a radius u times the base radius, so its slice has u² times the cylinder’s slice area. Adding all these slices gives Vcone/Vcylinder = ∫₀¹ u² du = 1/3. Drag the yellow slice to see how its radius and area change.","manimCode":"const heading = new Text({ text: 'Why a cone holds one third', fontSize: 30, color: WHITE });
heading.moveTo([0, 3.25, 0]);
const leftHeading = new Text({ text: 'Same base and height', fontSize: 19, color: GRAY });
leftHeading.moveTo([-4.45, 2.45, 0]);
const graphHeading = new Text({ text: 'Slice area / base area', fontSize: 20, color: WHITE });
graphHeading.moveTo([0, 2.45, 0]);
scene.add(heading, leftHeading, graphHeading);

let u = 0.65;
const cx = -4.45;
const topY = 1.65;
const baseY = -1.75;
const height = topY - baseY;
const radius = 1.08;
function ovalPoints(x, y, rx, ry) {
  const pts = [];
  for (let i = 0; i < 64; i++) {
    const a = 2 * Math.PI * i / 64;
    pts.push([x + rx * Math.cos(a), y + ry * Math.sin(a), 0]);
  }
  return pts;
}
const cylinderOutline = new Polygon({ vertices: [[cx-radius, topY, 0], [cx+radius, topY, 0], [cx+radius, baseY, 0], [cx-radius, baseY, 0]], color: GRAY });
cylinderOutline.setFill(GRAY, 0.07);
const cylinderTop = new Polygon({ vertices: ovalPoints(cx, topY, radius, 0.19), color: GRAY });
cylinderTop.setFill(GRAY, 0.05);
const coneProfile = new Polygon({ vertices: [[cx, topY, 0], [cx-radius, baseY, 0], [cx+radius, baseY, 0]], color: BLUE });
coneProfile.setFill(BLUE, 0.16);
const sharedBase = new Polygon({ vertices: ovalPoints(cx, baseY, radius, 0.19), color: BLUE });
sharedBase.setFill(BLUE, 0.18);
const cylinderSlice = new Polygon({ vertices: ovalPoints(cx, 0, radius, 0.19), color: GRAY });
cylinderSlice.setFill(GRAY, 0.08);
const coneSlice = new Polygon({ vertices: ovalPoints(cx, 0, radius*u, 0.19*u), color: YELLOW });
coneSlice.setFill(YELLOW, 0.35);
const sliceHandle = new Dot({ point: [cx+radius*u, topY-height*u, 0], radius: 0.13, color: YELLOW });
const heightLine = new DashedLine({ start: [-5.9, topY, 0], end: [-5.9, baseY, 0], color: GRAY });
const heightLabel = new Text({ text: 'H', fontSize: 21, color: GRAY });
heightLabel.moveTo([-6.1, -0.05, 0]);
const baseLabel = new Text({ text: 'Base radius R', fontSize: 19, color: BLUE });
baseLabel.moveTo([cx, -2.2, 0]);
scene.add(cylinderOutline, cylinderTop, coneProfile, sharedBase, heightLine, heightLabel, baseLabel, cylinderSlice, coneSlice, sliceHandle);

const ax = new Axes({ xRange: [-0.1, 1.1, 0.2], yRange: [-0.1, 1.1, 0.2], xLength: 4, yLength: 4, tips: false });
const cylinderArea = new Polygon({ vertices: [ax.c2p(0,0), ax.c2p(1,0), ax.c2p(1,1), ax.c2p(0,1)], color: GRAY });
cylinderArea.setFill(GRAY, 0.1);
function areaVertices(end) {
  const pts = [ax.c2p(0,0)];
  for (let i = 0; i <= 60; i++) {
    const v = end*i/60;
    pts.push(ax.c2p(v, v*v));
  }
  pts.push(ax.c2p(end,0));
  return pts;
}
const totalArea = new Polygon({ vertices: areaVertices(1), color: BLUE });
totalArea.setFill(BLUE, 0.3);
const partialArea = new Polygon({ vertices: areaVertices(u), color: YELLOW });
partialArea.setFill(YELLOW, 0.22);
const cylinderGraph = ax.plot(v => 1, { xRange: [0,1], color: GRAY });
const coneGraph = ax.plot(v => v*v, { xRange: [0,1], color: BLUE });
const guide = new DashedLine({ start: ax.c2p(u,0), end: ax.c2p(u,u*u), color: YELLOW });
const graphHandle = new Dot({ point: ax.c2p(u,u*u), radius: 0.12, color: YELLOW });
const xLabel = new Text({ text: 'u = distance from tip / H', fontSize: 17, color: GRAY });
xLabel.moveTo([0, -2.2, 0]);
const curveLabel = new Text({ text: 'cone: u²', fontSize: 18, color: BLUE });
curveLabel.moveTo([0.15, 0.9, 0]);
const cylinderLabel = new Text({ text: 'cylinder: 1', fontSize: 17, color: GRAY });
cylinderLabel.moveTo([0, 1.95, 0]);
scene.add(cylinderArea, totalArea, partialArea, ax, cylinderGraph, coneGraph, guide, graphHandle, xLabel, curveLabel, cylinderLabel);

const distanceReadout = new Text({ text: '', fontSize: 23, color: YELLOW });
distanceReadout.moveTo([4.35, 1.55, 0]);
const radiusReadout = new Text({ text: '', fontSize: 20, color: WHITE });
radiusReadout.moveTo([4.35, 0.95, 0]);
const areaReadout = new Text({ text: '', fontSize: 20, color: YELLOW });
areaReadout.moveTo([4.35, 0.35, 0]);
const volumeCaption = new Text({ text: 'Cone volume from tip', fontSize: 19, color: GRAY });
volumeCaption.moveTo([4.35, -0.45, 0]);
const volumeReadout = new Text({ text: '', fontSize: 21, color: YELLOW });
volumeReadout.moveTo([4.35, -0.9, 0]);
const totalCaption = new Text({ text: 'At the base: 33.33%', fontSize: 20, color: BLUE });
totalCaption.moveTo([4.35, -1.65, 0]);
scene.add(distanceReadout, radiusReadout, areaReadout, volumeCaption, volumeReadout, totalCaption);

const equation = new MathTex({ latex: '\\frac{V_{\\mathrm{cone}}}{V_{\\mathrm{cylinder}}}=\\int_0^1 u^2\\,du=\\left[\\frac{u^3}{3}\\right]_0^1=\\frac13' });
await equation.waitForRender();
equation.scale(0.8);
equation.moveTo([0, -2.85, 0]);
const hint = new Text({ text: 'Drag the yellow slice or the yellow graph point', fontSize: 19, color: GRAY });
hint.moveTo([0, -3.45, 0]);
scene.add(equation, hint);

function update() {
  const sliceY = topY-height*u;
  cylinderSlice.setVertices(ovalPoints(cx, sliceY, radius, 0.19));
  coneSlice.setVertices(ovalPoints(cx, sliceY, radius*u, 0.19*u));
  sliceHandle.moveTo([cx+radius*u, sliceY, 0]);
  graphHandle.moveTo(ax.c2p(u,u*u));
  guide.setStart(ax.c2p(u,0));
  guide.setEnd(ax.c2p(u,u*u));
  partialArea.setVertices(areaVertices(u));
  distanceReadout.setText('u = ' + u.toFixed(2));
  radiusReadout.setText('Radius = ' + u.toFixed(2) + ' R');
  areaReadout.setText('Slice area = ' + (100*u*u).toFixed(1) + '%');
  volumeReadout.setText((100*u*u*u/3).toFixed(2) + '% of full cylinder');
}
update();
makeDraggable(sliceHandle, scene, { onDrag: (mob, pos) => {
  u = Math.max(0.02, Math.min(1, (topY-pos[1])/height));
  update();
} });
makeDraggable(graphHandle, scene, { onDrag: (mob, pos) => {
  u = Math.max(0.02, Math.min(1, ax.pointToCoords(pos)[0]));
  update();
} });
await scene.wait(999999);"}

